const assert = require('assert');
const { v4: uuidv4 } = require('uuid');
const crypto = require('node:crypto');

// Test that uuidv4 produces a valid UUID
const id1 = uuidv4();
assert(id1.length === 36);
assert(id1.match(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/));

console.log('UUID test passed');

